import { Session } from '../sessions/session.js';
/** The RAG file a chunk came from, identified by its display name. */
export interface SourceIdentity {
    appName: string;
    userId: string;
    sessionId: string;
}
/** One line of a stored transcript. */
export interface TranscriptEvent {
    author: string;
    /** Epoch milliseconds. The transcript itself stores seconds. */
    timestamp: number;
    text: string;
}
/**
 * Builds the `displayName` under which a session's transcript is stored.
 *
 * The identifiers are encoded because they may contain dots, which the legacy
 * dot-delimited form cannot represent unambiguously.
 */
export declare function buildSourceDisplayName(appName: string, userId: string, sessionId: string): string;
/**
 * Recovers the identifiers from a `displayName`, or returns `undefined` when
 * the name is malformed or ambiguous.
 *
 * Two forms are read. The prefixed form is the one both this service and
 * adk-python write, so a corpus either writes stays readable by the other. The
 * unprefixed `{app}.{user}.{session}` form is read only: adk-python wrote it
 * before it adopted the prefix, and no writer here emits it.
 *
 * A dot-delimited name with four or more parts is ambiguous:
 * `demo.alice.smith.s1` names either user `alice` or user `alice.smith`.
 * Accepting it would hand one user another user's memories, so it is rejected.
 */
export declare function parseSourceDisplayName(displayName: string): SourceIdentity | undefined;
/**
 * Renders a session as the newline-delimited JSON transcript that both ADK
 * implementations read, one object per text-bearing event.
 *
 * The timestamp is written in seconds because adk-python writes seconds; a
 * corpus is shared between the two.
 */
export declare function serializeSessionTranscript(session: Session): string;
/**
 * Reads the events out of a retrieved transcript chunk.
 *
 * A line that is not JSON is skipped: a corpus may hold files this service
 * never wrote.
 */
export declare function parseTranscriptEvents(text: string): TranscriptEvent[];
